function ActivityMountainDrawItemCell:RefreshItemShow(data)
	self.data = data
	self:RefreshShow()
end

function ActivityMountainDrawItemCell:RefreshShow()
	---@type GoodNodeMB
	local goodEnv = CfUtils.GetLuaScr(self.GoodNode, "Game.Behaviours.GoodNodeMB")
	local goodsId = self.data.rewards[1].goodsId
	goodEnv:Reload({
		goodsId = goodsId,
		text = string.format("x%d", self.data.rewards[1].num),
		isShowNo = true
	})
	
	goodEnv:SetClickCallback(function()
		local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
		if isTable(vo) then
			GameUtils.ShowCommonTipsBoard(self.GoodNode.gameObject, vo.name, vo.desc, vo.quality, vo.id)
		end
	end)
	
	if self.data.stock < 0 then
		CfUtils.FillText(self.TextNumber,localize("∞"))
		goodEnv:SetSanXingGainShow(false)
		CfUtils.SetActive(self.ImgFinish,false)
		CfUtils.SetUISwitchImage(self.ImgBg1,1)
	else
		CfUtils.FillText(self.TextNumber,string.format("%s/%s",self.data.currentStock,self.data.stock))
		goodEnv:SetSanXingGainShow(checkNumber(self.data.currentStock) <= 0)
		CfUtils.SetActive(self.ImgFinish,checkNumber(self.data.currentStock) <= 0)
		CfUtils.SetUISwitchImage(self.ImgBg1,checkNumber(self.data.currentStock) <= 0 and 2 or 1)
	end
end

function ActivityMountainDrawItemCell:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return ActivityMountainDrawItemCell